package com.xdownload.mobile;import org.junit.Test;import static org.junit.Assert.*;public class PerformancePolicyTest{@Test public void thermalAndBatteryLimits(){assertEquals(1,PerformancePolicy.jobs(3,false,true,false));assertEquals(1,PerformancePolicy.connections(2,8,100000000,false,true,false,false,1));assertEquals(1,PerformancePolicy.connections(0,8,100000000,false,false,false,false,1));}@Test public void networkAndWorkloadCaps(){assertEquals(8,PerformancePolicy.connections(2,32,100000000,false,false,false,false,1));assertEquals(3,PerformancePolicy.connections(2,8,100000000,false,false,false,true,1));assertEquals(3,PerformancePolicy.connections(2,8,100000000,false,false,false,false,2));assertEquals(3,PerformancePolicy.jobs(20,false,false,false));}@Test public void hyperEngineCapsAndRetry(){assertEquals(32,PerformancePolicy.connections(4,32,600L*1024*1024,false,false,false,false,1));assertEquals(32,PerformancePolicy.connections(4,32,200L*1024*1024,false,false,false,false,1));assertEquals(3,PerformancePolicy.connections(2,32,600L*1024*1024,false,false,false,true,1));assertEquals(8,PerformancePolicy.connections(2,32,600L*1024*1024,false,false,false,false,1));assertFalse(PerformancePolicy.retryable("HTTP 429"));assertFalse(PerformancePolicy.retryable("Storage full"));assertTrue(PerformancePolicy.retryable("HTTP 503"));assertEquals(2000L,PerformancePolicy.retryDelay(1));assertEquals(Long.MAX_VALUE,ParallelEngine.boundary(Long.MAX_VALUE,32,32));}@Test public void customRateHonorsMode(){assertEquals(0,PerformancePolicy.rate(1,0));assertEquals(256*1024L,PerformancePolicy.rate(2,256));assertEquals(512*1024L,PerformancePolicy.rate(0,1024));assertEquals(1024*1024L,PerformancePolicy.rate(3,0));}}